\begin{lemma}[A dense compressed target]
\label{p13:transfer:compressed-target}
For fixed sources and a fixed channel of good pairs, the number of
compressed centers $X$ for which
$\dim(S(U_X)\cap W)\geq\eta L$ is $O_{s,C,\eta,\varepsilon}(N^\varepsilon)$.
\end{lemma}

\begin{lemma}[Several small kernels in one window]
\label{p13:transfer:small-kernels}
Fix $A>2$, $0<b,u<1$, and an integer $m$ with $m(1-b)>1$.
For $Y=(\log N)^A$, the number of windows containing $m$ distinct
values with $K_Y(n)\leq N^b$ and $a_Y(n)^2\leq N^u$ is
\begin{equation}
 \ll N^{\max(1-1/A,(1+u)/2)+\varepsilon}.
 \label{p13:transfer:small-kernels-bound}
\end{equation}
Also, the set $\mathcal X_q$ of windows containing distinct $n_1,n_2$
with $K_H(n_1)K_H(n_2)\leq N^q$ has cardinality
$O(N^{q+\varepsilon})$, for fixed $q\geq0$.
\end{lemma}

\begin{lemma}[Uniform independent deficit]
\label{p13:transfer:independent-deficit}
For fixed $s,u,C$ and every $\varepsilon>0$,
\begin{equation}
 E_W(u)\ll_{s,u,C,\varepsilon}N^{-1/2+\varepsilon},
 \label{p13:transfer:independent-bound}
\end{equation}
uniformly in the sources and $W$. The sum includes all cardinalities.
\end{lemma}

\begin{lemma}[Independent full-support tails]
\label{p13:transfer:independent-tail}
For every fixed weight $v>0$ and $a<2$, there is a fixed integer $s$
such that
\begin{equation}
 \sum_{\substack{|F|\geq s\\F\text{ has a full-support relation}}}
                  \prod_{x\in F}(vp_x)
 \ll N^{-a+\varepsilon}.
 \label{p13:transfer:tail-independent}
\end{equation}
The same conclusion holds with one block of any of the fixed compressed
types, weighted by $vp$. For this version the remaining factors are
$vp_x$.
\end{lemma}

\begin{lemma}[Certificate budgets with several anchors]
\label{p13:transfer:anchor-budgets}
Choose an even integer $t\geq2$, $A_0>1$, $0<b<1$, and
$1/2<\sigma<1$ with $A_0(1-\sigma)<1$. Put
\[
 \delta=(1-b)(1-\sigma),\qquad \theta=t/A_0.
\]
Suppose each unmarked block in a family has a relation selecting at
least $t$ values in that block; the relation may depend on the block.
Mark a block when some value has odd kernel above
$Y=(\log N)^{A_0}$ at most $N^b$.
Under any fixed independent weight per block, the moderate certificates
have total mass
\begin{equation}
 N^{-tb+2t/A_0+o(1)}.
 \label{p13:transfer:moderate-budget}
\end{equation}
If $\theta+\delta<1$, the saturated families of size at least $s$
have total independent mass
\begin{equation}
 N^{-s\delta/2+o(1)}.
 \label{p13:transfer:saturated-budget}
\end{equation}
\end{lemma}

\begin{proposition}[Independent extensions at the critical order]
\label{p1:uniform:branching}
Put \(H=\log N\), \(h=\log H\), and fix \(K>0\).
For every \(j\le KH/h\) source windows, there is
an exceptional set of new centres of size at most
\(D_N^*\), where
\begin{equation}
 \log D_N^*
 \le\frac23H-\frac{H\log h}{9h}+O_{K,C}(H/h),
 \label{p1:uniform:branching-rate}
\end{equation}
such that outside it the \(L\) new relative bits
are exactly uniform and independent of all
previously exposed values.
\end{proposition}

\begin{proposition}[Polylogarithmic confinement]
\label{p1:consequences:confinement}
For every fixed $c>0$ and $\varepsilon>0$, there is a fixed
integer $k$ such that, outside a mass
\begin{equation}
 O_{c,\beta,\varepsilon}
 \left(N^{-\min\{\beta-6/5,\,\beta-1-2/c\}+\varepsilon}\right),
 \label{p1:consequences:confinement-error}
\end{equation}
one has
\begin{equation}
 \#\{u:G_u>B^c\}
       \le k-1+\left\lfloor\frac{\log N}{c\log B}\right\rfloor=o(L).
 \label{p1:consequences:confinement-count}
\end{equation}
The same assertion holds for $\#\{q\in\mathcal Q:q>B^c\}$.
On a family of $B^{O(1)}$ fixed affine planes for the centers,
replace $2/c$ in the exceptional mass by $1/c$.
For original triples, $c>6$ is therefore sufficient for an
exceptional mass $o(LN^{-2/3})$; on these planes $c>3$
suffices. These are sufficient thresholds, not optimality claims.
\end{proposition}
